modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.Differentiator;
end Baseline;
model FINDING00817
  extends Modelica.Electrical.Analog.Examples.OpAmps.Differentiator(f=0);
end FINDING00817;
model FINDING00814
  extends Modelica.Electrical.Analog.Examples.OpAmps.Differentiator(der_(R=0));
end FINDING00814;
model FinalFINDING00817
  extends Modelica.Electrical.Analog.Examples.OpAmps.Differentiator(final f=0);
end FinalFINDING00817;
model FinalFINDING00814
  extends Modelica.Electrical.Analog.Examples.OpAmps.Differentiator(der_(final R=0));
end FinalFINDING00814;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00817\n");
simulate(FINDING00817, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00814\n");
simulate(FINDING00814, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00817\n");
simulate(FinalFINDING00817, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00814\n");
simulate(FinalFINDING00814, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00817\n");
system("./Baseline -override f=0 -r=FINDING00817_override.csv");
print("AUDIT_OVERRIDE FINDING00814\n");
system("./Baseline -override der_.R=0 -r=FINDING00814_override.csv");
